        '    log = []\n'
        '    trials = []\n'
        "    results_path = args.output.with_suffix('.json')\n"
        "    previous_browser_path = os.environ.get('PLAYWRIGHT_BROWSERS_PATH')\n"
        "    os.environ['PLAYWRIGHT_BROWSERS_PATH'] = str(args.cache_dir.resolve() / 'playwright')\n"
        '    try:\n'
