# ---------------------------------------------------------------------------
# Optional source-built exact-inplace LeakyReLU experiment. All old routes and
# source catalogues remain unchanged. This milestone deliberately supports OFF
# only, the frozen 3 x 5 paired design, and the original model/query fixture.
# ---------------------------------------------------------------------------
INPLACE_PARENT_SHA256 = '10edbd6a4cc120c7bab10ff40b47e41f880e54f3ba46756e78de88fa6d41facf'
INPLACE_SCHEMA = 'voicevox-one-file-inplace-leaky-v1'
INPLACE_MODES = ('original', 'rebuilt', 'candidate')
INPLACE_LABELS = {
    'original': 'Released activation + forced loadsplat',
    'rebuilt': 'Unmodified activation source rebuild',
    'candidate': 'Exact-inplace LeakyReLU SIMD source candidate',
}
INPLACE_REQUIRED_CONFIRMATION = {
    'source_confirmation.py', 'source_validate.py', 'source_manifest.py',
    'source_resources.py', 'source_quality.py', 'source_worker.js', 'source_alias_check.js',
}


def validate_inplace_arguments(args: argparse.Namespace) -> None:
    if not args.inplace_leaky_experiments:
        return
    kernel_require(__debug__, 'source experiments require Python integrity assertions; do not use -O')
    kernel_require(sys.platform.startswith('linux') and platform.machine().lower() in {'x86_64', 'amd64'},
                   'source experiment currently supports x86-64 Linux/WSL only')
    kernel_require(args.threads == 2 and args.style_id == 302 and args.target_seconds == 10
                   and args.audio_query is None, 'source study requires --threads 2, Style302 and prepared_query(10)')
    kernel_require(args.seed == 1729, 'source study freezes the paired design; use --seed 1729')
    kernel_require(not any((args.experiments, args.baseline_only, args.backend_experiments,
                            args.graph_experiments, args.kernel_experiments, args.research_manifest,
                            args.report_from, args.research_screen, args.measurement_gate,
                            args.headed, args.browser_path, args.audio_dir, args.spectrogram_dir,
                            args.threaded_ort_archive, args.threaded_ort_url,
                            args.xnnpack_ort_archive, args.xnnpack_ort_url)),
                   'run the source study separately using pinned headless Chromium, inputs and runtimes')
    kernel_require(args.graph_revectorize == 'off' and args.kernel_revectorize == 'off'
                   and not args.kernel_profile_xnn, 'source milestone is OFF only; other-route modifiers are unsupported')


def inplace_materialize_sources(directory: Path) -> dict[str, Path]:
    """Materialize the unchanged base catalogue and exact source-study payloads."""
    paths = kernel_materialize_sources(directory)
    kernel_require(set(INPLACE_EMBEDDED_SOURCES) == set(INPLACE_SOURCE_SHA256), 'source-study catalogue differs from pins')
    for name, source in INPLACE_EMBEDDED_SOURCES.items():
        kernel_require(Path(name).name == name, 'source-study payload must have a plain basename')
        data = source.encode('utf-8')
        kernel_require(hashlib.sha256(data).hexdigest() == INPLACE_SOURCE_SHA256[name], 'source-study SHA mismatch: ' + name)
        path = directory / 'inplace-source' / name
        path.parent.mkdir(parents=True, exist_ok=True)
        atomic_write(path, data)
        kernel_require(sha256_file(path) == INPLACE_SOURCE_SHA256[name], 'materialized source-study file changed')
        paths['inplace/' + name] = path
    return paths


def inplace_check_privacy(value: Any) -> None:
    """The reviewed result schema has byte/sample COUNTS, never byte arrays."""
    counts = {'wav_bytes', 'raw_bytes', 'fp32_samples', 'pcm_samples'}
    if isinstance(value, dict):
        for key, item in value.items():
            if str(key).lower() in counts:
                kernel_require(type(item) is int and item >= 0, 'waveform sizes must be integer counts, not payloads')
                continue
            # Reuse the original key ban, then traverse with the new count schema.
            kernel_check_report_privacy({key: None})
            inplace_check_privacy(item)
    elif isinstance(value, (tuple, list)):
        for item in value:
            inplace_check_privacy(item)
    else:
        kernel_check_report_privacy(value)


def inplace_check_artifacts(directory: Path) -> None:
    for path in directory.rglob('*'):
        if not path.is_file():
            continue
        kernel_require(path.suffix.lower() in {'.json', '.log', '.html', '.png'}, 'unexpected source-study result file type')
        with path.open('rb') as stream:
            prefix = stream.read(12)
        kernel_require(not prefix.startswith((b'RIFF', b'fLaC', b'OggS')), 'audio bytes in source-study results')
        if path.suffix.lower() == '.json':
            inplace_check_privacy(json.loads(path.read_text('utf-8')))
        elif path.suffix.lower() in {'.log', '.html'}:
            text = path.read_text('utf-8', errors='replace').lower()
            kernel_require(not any(token in text for token in ('wav_base64', 'data:audio/', '"audio_outputs"')),
                           'audio payload marker in source-study results')


def inplace_public_manifest(manifest: dict[str, Any]) -> dict[str, Any]:
    """Retain source/build proof while omitting paths to model and executable assets."""
    public = {key: value for key, value in manifest.items() if key not in ('variants', 'cpu_reference')}
    public['variants'] = [{key: value for key, value in row.items() if key not in ('binary', 'model')}
                          for row in manifest['variants']]
    if 'cpu_reference' in manifest:
        public['cpu_reference'] = {key: value for key, value in manifest['cpu_reference'].items() if key != 'binary'}
    inplace_check_privacy(public)
    return public


def inplace_summary(confirmation: dict[str, Any]) -> dict[str, Any]:
    """Descriptive paired effects only; the embedded validator owns all gates."""
    kernel_require(confirmation['schema'] == 'inplace-leaky-source-confirmation-v1'
                   and confirmation['status'] == 'complete', 'source confirmation is not complete')
    rows = confirmation['trials']
    kernel_require(len(rows) == 45 and set(row['mode'] for row in rows) == set(INPLACE_MODES), 'expected all 45 source-study calls')
    paired = {}
    for row in rows:
        key = (row['process_set'], row['pair'])
        kernel_require(row['mode'] not in paired.setdefault(key, {}), 'duplicate source-study observation')
        kernel_require(type(row['elapsed_s']) in (int, float) and math.isfinite(row['elapsed_s'])
                       and row['elapsed_s'] > 0, 'invalid source-study duration')
        paired[key][row['mode']] = row['elapsed_s']
    kernel_require(set(paired) == {(group, pair) for group in (1, 2, 3) for pair in range(1, 6)}
                   and all(set(row) == set(INPLACE_MODES) for row in paired.values()), 'incomplete paired source design')
    comparisons = {}
    for control in ('original', 'rebuilt'):
        reductions = [100 * (1 - row['candidate'] / row[control]) for row in paired.values()]
        comparisons[control] = {
            'paired_observations': 15,
            'median_paired_reduction_percent': statistics.median(reductions),
            'geomean_speedup': statistics.geometric_mean(row[control] / row['candidate'] for row in paired.values()),
            'process_set_effects': [
                {'process_set': group, 'paired_observations': 5,
                 'geomean_speedup': statistics.geometric_mean(row[control] / row['candidate']
                    for (set_id, _), row in paired.items() if set_id == group)} for group in (1, 2, 3)],
        }
    return {
        'primary_calls': 45,
        'latency': {mode: {'observations': 15, 'median_seconds': statistics.median(
                       row['elapsed_s'] for row in rows if row['mode'] == mode)} for mode in INPLACE_MODES},
        'candidate_vs_control': comparisons,
        'sampling_policy': 'No CPU companion or high-frequency trace. Pre/post resource boundaries and one untimed idle-tree observation per process set only.',
        'cpu_quality': confirmation['cpu_quality']['forced_loadsplat_vs_cpu'],
        'fault_exposed_calls': sum(bool(row.get('resource_observations', {}).get('fault_exposed')) for row in rows),
    }


def inplace_latency_svg(confirmation: dict[str, Any]) -> str:
    rows = confirmation['trials']
    high = max(row['elapsed_s'] for row in rows) * 1.08
    width, height, left, top = 760, 250, 65, 20
    plot_w, plot_h = 650, 175
    colors = {'original': '#4773c4', 'rebuilt': '#8a65b5', 'candidate': '#008575'}
    parts = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="All 45 primary latencies by paired round">',
             f'<path d="M{left},{top}V{top+plot_h}H{left+plot_w}" fill="none" stroke="#789"/>']
    for tick in range(5):
        value = high * tick / 4
        y = top + plot_h * (1 - tick / 4)
        parts.append(f'<text x="{left-8}" y="{y+4:.1f}" text-anchor="end" font-size="11">{value:.3f}s</text>')
    for group in (1, 2):
        x = left + (group * 5 - .5) / 14 * plot_w
        parts.append(f'<path d="M{x:.1f},{top}V{top+plot_h}" stroke="#bbc" stroke-dasharray="3 4"/>')
    for mode in INPLACE_MODES:
        values = sorted((row for row in rows if row['mode'] == mode), key=lambda row: (row['process_set'], row['pair']))
        points = ' '.join(f'{left+i/14*plot_w:.1f},{top+plot_h*(1-row["elapsed_s"]/high):.1f}' for i, row in enumerate(values))
        parts.append(f'<polyline points="{points}" fill="none" stroke="{colors[mode]}" stroke-width="2"/>')
        for i, row in enumerate(values):
            parts.append(f'<circle cx="{left+i/14*plot_w:.1f}" cy="{top+plot_h*(1-row["elapsed_s"]/high):.1f}" r="3" fill="{colors[mode]}"><title>{html.escape(mode)} set {row["process_set"]}, pair {row["pair"]}: {row["elapsed_s"]:.6f}s</title></circle>')
    for i, mode in enumerate(INPLACE_MODES):
        parts.append(f'<text x="{left+i*225}" y="230" font-size="12" fill="{colors[mode]}">{html.escape(mode)}</text>')
    parts.append('<text x="380" y="212" text-anchor="middle" font-size="11">Paired rounds 1–15; dashed boundaries separate fresh process sets</text></svg>')
    return ''.join(parts)


def render_inplace_report(result: dict[str, Any], output: Path) -> None:
    kernel_require(result.get('schema') == INPLACE_SCHEMA and result.get('status') == 'complete', 'incomplete source-study report')
    inplace_check_privacy(result)
    confirmation, summary = result['confirmation'], result['summary']
    esc = lambda item: html.escape(str(item))
    latency = ''.join(f'<tr><td>{esc(INPLACE_LABELS[mode])}</td><td>{row["observations"]}</td><td>{row["median_seconds"]:.6f}</td></tr>'
                      for mode, row in summary['latency'].items())
    effects = ''.join(f'<li>Candidate versus {esc(INPLACE_LABELS[control])}: {value["median_paired_reduction_percent"]:.2f}% median paired latency reduction; {value["geomean_speedup"]:.3f}× geometric-mean speedup</li>'
                      for control, value in summary['candidate_vs_control'].items())
    dispatch_rows = []
    idle_rows = []
    for group in confirmation['process_sets']:
        for mode in INPLACE_MODES:
            proof = group['runtime'][mode]['dispatch']
            dispatch_rows.append(f'<tr><td>{group["id"]}</td><td>{esc(mode)}</td><td>{esc(proof["actual_dispatch"])}</td><td>{proof["worker_hardware_concurrency"]}</td><td>{proof["checked_pointers"]}</td></tr>')
            idle = group['idle']['modes'][mode]
            idle_rows.append(f'<tr><td>{group["id"]}</td><td>{esc(mode)}</td><td>{idle["cpu_percent"]:.3f}%</td><td>{idle["unmatched_processes"]}</td></tr>')
    csv_text = io.StringIO()
    writer = csv.DictWriter(csv_text, fieldnames=['process_set', 'pair', 'mode', 'elapsed_s', 'wav_bytes'])
    writer.writeheader()
    writer.writerows({key: row[key] for key in writer.fieldnames} for row in confirmation['trials'])
    provenance = {'distribution': confirmation.get('distribution'), 'preparation': result['manifest'],
                  'runtime_provenance': confirmation['provenance'], 'source_proof': confirmation['source_proof'],
                  'worker_source_sha256': confirmation['worker_source_sha256'], 'source_hashes': confirmation['source_hashes']}
    document = f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>VOICEVOX exact-inplace LeakyReLU source experiment</title><style>body{{font:16px system-ui;max-width:1100px;margin:auto;padding:24px;color:#172334}}table{{border-collapse:collapse;width:100%}}th,td{{text-align:left;border-bottom:1px solid #ccd;padding:8px}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef2f7;padding:12px}}details{{margin:18px 0}}h1{{font-size:26px}}svg{{width:100%;height:auto}}</style>
<h1>Exact-inplace LeakyReLU SIMD source experiment</h1>
<p>Actual measured source-build milestone. All three conditions use forced loadsplat, strict ordinary-SIMD FP32, V8 revectorization OFF and normal tiering. Original model, Style302, prepared_query(10), fixed vocoder shape, global ORT1 / XNN2 and spinning off.</p>
<p>The candidate changes the reviewed CPU activation source for exactly aliased float buffers. The rebuilt control uses unmodified reconstructed source. All other ordered native payloads are checked, including the duplicate activation member, dispatcher and real pthreadpool. No six-byte WASM guard edit is used by this option.</p>
<p>Three fresh process sets × five paired rounds × three conditions: 45 primary calls. Alias hooks run only in the separate correctness gate; primary workers are hook-free. Per-mode repeats and pre/post raw FP32/PCM equality to the forced-loadsplat control are required. All observations are retained; {summary['fault_exposed_calls']} calls were exposed to target major faults. This is experimental, host-specific evidence; a negative reduction means slower.</p>
<table><thead><tr><th>Condition</th><th>Observations</th><th>Median seconds</th></tr></thead><tbody>{latency}</tbody></table><ul>{effects}</ul>
{inplace_latency_svg(confirmation)}
<h2>Actual CORE worker dispatch</h2><table><thead><tr><th>Process set</th><th>Condition</th><th>Actual family</th><th>Worker hardwareConcurrency</th><th>Pointers checked</th></tr></thead><tbody>{''.join(dispatch_rows)}</tbody></table>
<h2>Same-run CPU reference</h2><p>After every primary browser closed, the original CPU2 and forced-loadsplat XNN2 outputs were checked with two repeats in sequential browsers. Candidate equality is to forced-loadsplat XNN; CPU bit-exactness is not assumed. Measured errors:</p><pre>{esc(json.dumps(summary['cpu_quality'], indent=2))}</pre>
<h2>CPU and resource observations</h2><p>{esc(summary['sampling_policy'])} The idle percentages below describe the untimed idle window, not inference CPU utilization. 100% denotes one logical CPU. Full boundary snapshots and memory/fault/swap context remain in the numeric JSON.</p>
<table><thead><tr><th>Process set</th><th>Condition</th><th>Idle CPU</th><th>Unmatched processes</th></tr></thead><tbody>{''.join(idle_rows)}</tbody></table>
<details><summary>All 45 primary observations (CSV)</summary><pre>{esc(csv_text.getvalue())}</pre></details>
<details><summary>Paired effects and three process-set clusters</summary><pre>{esc(json.dumps(summary['candidate_vs_control'], indent=2))}</pre></details>
<details><summary>Actual untimed alias and output gates</summary><pre>{esc(json.dumps(confirmation['browser_gate'], indent=2))}</pre></details>
<details><summary>Source, build, archive and distribution provenance</summary><pre>{esc(json.dumps(provenance, indent=2))}</pre></details>
<p>Private temporary waveform/model copies and helpers were removed after verified subprocess cleanup. Reports contain numeric metrics and hashes only. No upload or publication is performed by this program.</p></html>'''
    atomic_write(output, document.encode('utf-8'))


def inplace_emit_validated_log(path: Path) -> None:
    """Emit only the frozen validator's bounded JSON record protocol."""
    allowed = {'SOURCE_CONFIRM_SUMMARY', 'SOURCE_CONFIRM_META', 'SOURCE_CONFIRM_GATE',
               'SOURCE_CONFIRM_SET', 'SOURCE_CONFIRM_WARMUP', 'SOURCE_CONFIRM_CHECK',
               'SOURCE_CONFIRM_TRIAL', 'SOURCE_CONFIRM_CPU_QUALITY'}
    records = []
    for line in path.read_text('utf-8').splitlines():
        if not line.strip():
            continue
        prefix, separator, payload = line.partition(' ')
        kernel_require(separator and prefix in allowed, 'unexpected source-validator console record')
        value = json.loads(payload)
        inplace_check_privacy(value)
        records.append(prefix + ' ' + json.dumps(value, separators=(',', ':'), allow_nan=False))
    kernel_require(records, 'source validator produced no numeric console evidence')
    for line in records:
        print(line, flush=True)


def inplace_validate_saved_confirmation(confirmation: dict[str, Any]) -> dict[str, Any]:
    kernel_require(sys.platform.startswith('linux'), 'source-result replay currently requires Linux/WSL subprocess verification')
    kernel_require(INPLACE_CONFIRMATION_FROZEN, 'saved source-result validation requires frozen helper sources')
    inplace_check_privacy(confirmation)
    with kernel_private_directory() as directory:
        work = Path(directory)
        files = inplace_materialize_sources(work)
        source = work / 'confirmation.json'
        target = work / 'summary.json'
        atomic_write(source, json.dumps(confirmation, allow_nan=False).encode())
        env = dict(os.environ)
        env.pop('PYTHONOPTIMIZE', None)
        env['PYTHONUNBUFFERED'] = '1'
        temporary = work / 'temporary'
        temporary.mkdir(mode=0o700)
        for name in ('TMPDIR', 'TMP', 'TEMP'):
            env[name] = str(temporary)
        kernel_run_checked([sys.executable, str(files['inplace/source_validate.py']), str(source),
                            '--output', str(target)], work / 'validation.log', env)
        return json.loads(target.read_text('utf-8'))


def inplace_report_from(saved: dict[str, Any], output: Path) -> None:
    """Validate saved numeric evidence and render, with no build/model/browser."""
    if saved.get('schema') == INPLACE_SCHEMA:
        kernel_require(saved.get('status') == 'complete' and saved.get('private_helpers_deleted') is True,
                       'saved source-study wrapper is incomplete')
        confirmation = saved['confirmation']
        result = dict(saved)
    else:
        kernel_require(saved.get('schema') == 'inplace-leaky-source-confirmation-v1', 'unknown source result schema')
        confirmation = saved
        result = {'schema': INPLACE_SCHEMA, 'status': 'complete', 'confirmation': confirmation,
                  'private_helpers_deleted': True,
                  'manifest': {'recorded_manifest_sha256': confirmation['source_proof']['manifest_sha256'],
                               'replay_note': 'Reconstructed from validated numeric confirmation. The full local preparation manifest is not present in this saved record.'}}
    inplace_check_privacy(result)
    result['validated_summary'] = inplace_validate_saved_confirmation(confirmation)
    result['summary'] = inplace_summary(confirmation)
    render_inplace_report(result, output)


