        ' const slot=pin.callback_table.slot,index=pin.absolute_function_index;\n'
        " if(!Number.isInteger(slot)||slot<0||slot>=table.length||!Number.isInteger(index))throw Error('Invalid callback table mapping');\n"
        ' const original=table.get(slot);\n'
        " if(typeof original!=='function'||original.name!==String(index))throw Error('Actual callback identity differs from module mapping');\n"
        " const result={variant,table_slot:slot,function_index:index,callbacks:0,elements:0,classes:{},predicted_branch:{simd:{calls:0,elements:0},scalar:{calls:0,elements:0}},length_histogram:{},restored:false,metadata_errors:0,scope:'Observed actual pointers and verified Wasm guard; eligibility evidence, not hardware branch tracing.'};\n"
        ' const hook=leakyForwarder((context,beginPtr,endPtr)=>{\n'
        '  try{\n'
        '   const h=new Uint32Array(module.HEAPU8.buffer),u=[context,beginPtr,endPtr].map(x=>x>>>0);\n'
